static int CalculateMaxDifferenceSum(List<Integer> sequence) {
    int total_sum = 0;
    int n = sequence.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            int diff = sequence.get(j) - sequence.get(i);
            if (diff > 0) {
                total_sum += diff;
            }
        }
    }
    return total_sum;
}
